package thaumcraft.verification;

import java.util.*;
import java.util.function.BiConsumer;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.level.material.PushReaction;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import thaumcraft.blocks.*;
import thaumcraft.items.ArcaneKeyItem;
import thaumcraft.registry.*;

/** Actual placement, interaction, break events and saved-world reload. */
final class OwnedBlockVerification {
    private static final BlockPos POS=new BlockPos(2240,150,32);
    private static final UUID OWNER=UUID.fromString("b351c5d5-bb50-4853-9824-fb8b81c2a274"),USER=UUID.fromString("b351c5d5-bb50-4853-9824-fb8b81c2a275"),ADMIN=UUID.fromString("b351c5d5-bb50-4853-9824-fb8b81c2a276");
    private static FakePlayer player(ServerLevel l,UUID id,String name){var p=new FakePlayer(l,new GameProfile(id,name));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(POS.getCenter().add(0,3,-4));return p;}
    private static UseOnContext context(FakePlayer p,BlockPos pos,Direction side){return new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(pos.getCenter().add(Vec3.atLowerCornerOf(side.getNormal()).scale(.5)),side,pos,false));}
    private static OwnedBlockEntity tile(ServerLevel l,BlockPos p){return (OwnedBlockEntity)l.getBlockEntity(p);}
    private static ItemStack bind(FakePlayer p,BlockPos pos,Item key){p.getInventory().clearContent();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(key,2));key.onItemUseFirst(p.getMainHandItem(),context(p,pos,Direction.NORTH));return p.getInventory().items.stream().filter(s->s.is(key)&&ArcaneKeyItem.bound(s)).findFirst().orElse(ItemStack.EMPTY).copy();}
    static void run(ServerLevel l,BiConsumer<Boolean,String> check){
        var owner=player(l,OWNER,"OriginalOwner");var user=player(l,USER,"Guest");var admin=player(l,ADMIN,"Administrator");boolean old=thaumcraft.config.ThaumcraftConfig.WARDED_STONE.get();
        try{thaumcraft.config.ThaumcraftConfig.WARDED_STONE.set(true);
            for(int x=-2;x<28;x++)for(int y=-1;y<4;y++)for(int z=-2;z<5;z++){var p=POS.offset(x,y,z);l.getChunkAt(p);l.setBlock(p,y==-1?Blocks.STONE.defaultBlockState():Blocks.AIR.defaultBlockState(),2);}
            for(int i=0;i<4;i++){
                var p=POS.offset(i*4,0,0);owner.setYRot(i*90-135);owner.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R4Content.ARCANE_DOOR_ITEM.get()));
                check.accept(owner.getMainHandItem().useOn(context(owner,p.below(),Direction.UP)).consumesAction(),"native arcane door placement for original yaw quadrant "+i);var s=l.getBlockState(p);
                check.accept(s.is(R4Content.ARCANE_DOOR.get())&&s.getValue(DoorBlock.FACING)==new Direction[]{Direction.EAST,Direction.SOUTH,Direction.WEST,Direction.NORTH}[i]&&!s.getValue(DoorBlock.OPEN)&&l.getBlockState(p.above()).getValue(DoorBlock.HALF)==DoubleBlockHalf.UPPER,"original orientation, closed placement and both halves: "+i);
                check.accept(tile(l,p).ownedBy(OWNER)&&tile(l,p.above()).ownedBy(OWNER)&&tile(l,p).ownerName().equals("OriginalOwner"),"both halves capture UUID and display name: "+i);
                var box=s.getShape(l,p).bounds();check.accept(Math.abs(Math.min(box.getXsize(),box.getZsize())-3/16d)<1e-9,"original three-sixteenths door thickness: "+i);
            }
            var door=POS;l.getBlockState(door).useWithoutItem(l,user,new BlockHitResult(door.getCenter(),Direction.NORTH,door,false));check.accept(!l.getBlockState(door).getValue(DoorBlock.OPEN),"unauthorized native interaction cannot open door");
            var iron=bind(owner,door.above(),R4Content.IRON_KEY.get());check.accept(!iron.isEmpty()&&owner.getMainHandItem().getCount()==1&&iron.hasFoil()&&iron.get(DataComponents.CUSTOM_DATA).copyTag().getLong("KeyPosition")==door.asLong(),"upper-half binding emits one glinting lower-position key and spends one blank");
            var gold=bind(owner,door,R4Content.GOLD_KEY.get());check.accept(!gold.isEmpty(),"owner can issue gold key");
            user.setItemInHand(InteractionHand.MAIN_HAND,iron.copy());user.getMainHandItem().getItem().onItemUseFirst(user.getMainHandItem(),context(user,door.above(),Direction.NORTH));check.accept(user.getMainHandItem().isEmpty()&&tile(l,door).permits(USER)&&!tile(l,door).administers(USER)&&tile(l,door.above()).permits(USER),"iron key consumed; both halves grant use without administration");
            l.getBlockState(door.above()).useWithoutItem(l,user,new BlockHitResult(door.above().getCenter(),Direction.NORTH,door.above(),false));check.accept(l.getBlockState(door).getValue(DoorBlock.OPEN)&&l.getBlockState(door.above()).getValue(DoorBlock.OPEN),"authorized upper click synchronizes both open halves");
            check.accept(bind(user,door,R4Content.IRON_KEY.get()).isEmpty()&&bind(user,door,R4Content.GOLD_KEY.get()).isEmpty(),"iron access cannot issue keys");
            admin.setItemInHand(InteractionHand.MAIN_HAND,gold.copy());admin.getMainHandItem().getItem().onItemUseFirst(admin.getMainHandItem(),context(admin,door,Direction.NORTH));check.accept(tile(l,door).administers(ADMIN)&&tile(l,door.above()).administers(ADMIN)&&admin.getMainHandItem().isEmpty(),"gold key consumed; both halves grant administration");
            check.accept(!bind(admin,door,R4Content.IRON_KEY.get()).isEmpty()&&bind(admin,door,R4Content.GOLD_KEY.get()).isEmpty(),"administrator can issue iron keys but cannot issue gold keys");
            var impostor=player(l,UUID.randomUUID(),"OriginalOwner");impostor.setItemInHand(InteractionHand.MAIN_HAND,iron.copy());impostor.getMainHandItem().getItem().onItemUseFirst(impostor.getMainHandItem(),context(impostor,door.offset(4,0,0),Direction.NORTH));check.accept(!tile(l,door.offset(4,0,0)).permits(impostor.getUUID())&&!impostor.getMainHandItem().isEmpty(),"bound key refuses different position without consumption");
            var renamed=player(l,OWNER,"RenamedOwner");check.accept(tile(l,door).ownedBy(renamed.getUUID())&&!tile(l,door).permits(impostor.getUUID()),"same UUID retains ownership after rename; same name with another UUID grants nothing");
            var copy=new OwnedBlockEntity(door,l.getBlockState(door));copy.loadWithComponents(tile(l,door).saveWithoutMetadata(l.registryAccess()),l.registryAccess());check.accept(copy.ownedBy(OWNER)&&copy.permits(USER)&&!copy.administers(USER)&&copy.administers(ADMIN)&&copy.ownerName().equals("OriginalOwner"),"native NBT preserves owner UUID, name and both access ranks");check.accept(!copy.getUpdateTag(l.registryAccess()).contains("Access")&&copy.getUpdateTag(l.registryAccess()).hasUUID("Owner"),"public block update omits private access list");
            l.setBlockAndUpdate(door.relative(Direction.NORTH),Blocks.REDSTONE_BLOCK.defaultBlockState());R4Content.ARCANE_DOOR.get().setOpen(null,l,l.getBlockState(door),door,false);l.neighborChanged(door,Blocks.REDSTONE_BLOCK,door.relative(Direction.NORTH));check.accept(!l.getBlockState(door).getValue(DoorBlock.OPEN),"ordinary redstone does not open arcane door");
            var plate=door.relative(Direction.SOUTH);l.setBlockAndUpdate(plate,R4Content.ARCANE_PLATE.get().defaultBlockState());R4Content.ARCANE_PLATE.get().setPlacedBy(l,plate,l.getBlockState(plate),owner,new ItemStack(R4Content.ARCANE_PLATE_ITEM.get()));tile(l,plate).grant(USER,0);tile(l,plate).grant(ADMIN,1);var block=R4Content.ARCANE_PLATE.get();var object=new ItemEntity(l,plate.getX()+.5,plate.getY()+.05,plate.getZ()+.5,new ItemStack(Items.COBBLESTONE));
            check.accept(block.accepts(owner,tile(l,plate))&&block.accepts(impostor,tile(l,plate)),"default plate accepts authorized and unauthorized players");tile(l,plate).setting=1;check.accept(!block.accepts(owner,tile(l,plate))&&!block.accepts(user,tile(l,plate))&&block.accepts(impostor,tile(l,plate))&&block.accepts(object,tile(l,plate)),"except-you mode excludes authorized players, accepts others and objects");tile(l,plate).setting=2;check.accept(block.accepts(owner,tile(l,plate))&&block.accepts(user,tile(l,plate))&&block.accepts(admin,tile(l,plate))&&!block.accepts(impostor,tile(l,plate))&&!block.accepts(object,tile(l,plate)),"just-you mode accepts authorized players exclusively");
            l.getBlockState(plate).useWithoutItem(l,user,new BlockHitResult(plate.getCenter(),Direction.UP,plate,false));check.accept(tile(l,plate).setting==2,"iron access cannot change plate mode");l.getBlockState(plate).useWithoutItem(l,admin,new BlockHitResult(plate.getCenter(),Direction.UP,plate,false));check.accept(tile(l,plate).setting==0&&l.getBlockState(plate).getValue(ArcanePressurePlateBlock.MODE)==0,"gold access cycles mode and native texture state");
            check.accept(l.addFreshEntity(object),"real item entity enters pressure plate fixture");block.checkEntities(l,plate);check.accept(l.getBlockState(plate).getValue(ArcanePressurePlateBlock.POWERED)&&l.getBlockState(door).getValue(DoorBlock.OPEN),"actual plate overlap opens adjacent door sharing owner");for(var direction:Direction.values())check.accept(l.getBlockState(plate).getSignal(l,plate,direction)==15&&l.getBlockState(plate).getDirectSignal(l,plate,direction)==15,"original strong and weak plate power on "+direction);object.discard();block.checkEntities(l,plate);check.accept(!l.getBlockState(plate).getValue(ArcanePressurePlateBlock.POWERED)&&!l.getBlockState(door).getValue(DoorBlock.OPEN),"removing entity releases plate and closes door");check.accept(l.getBlockState(plate).getCollisionShape(l,plate).isEmpty()&&l.getBlockState(plate).getShape(l,plate).bounds().maxY==1/16d,"original plate outline and empty collision");
            var foreign=door.relative(Direction.WEST);l.setBlockAndUpdate(foreign,R4Content.ARCANE_PLATE.get().defaultBlockState().setValue(ArcanePressurePlateBlock.POWERED,true));tile(l,foreign).assign(impostor);l.neighborChanged(door,block,foreign);check.accept(!l.getBlockState(door).getValue(DoorBlock.OPEN),"plate with unauthorized owner cannot open door");tile(l,foreign).assign(user);l.neighborChanged(door,block,foreign);check.accept(l.getBlockState(door).getValue(DoorBlock.OPEN),"plate owned by a door key user opens it");
            var glass=POS.offset(20,0,0);l.setBlockAndUpdate(glass,R4Content.WARDED_GLASS.get().defaultBlockState());R4Content.WARDED_GLASS.get().setPlacedBy(l,glass,l.getBlockState(glass),owner,new ItemStack(R4Content.WARDED_GLASS_ITEM.get()));for(var p:List.of(door,door.above(),glass,plate)){var s=l.getBlockState(p);check.accept(s.getDestroySpeed(l,p)==-1&&s.getPistonPushReaction()==PushReaction.BLOCK&&!s.canEntityDestroy(l,p,object),"protected hardness, piston and entity rejection: "+p);check.accept(!owner.gameMode.destroyBlock(p)&&l.getBlockState(p).equals(s),"native break event protects even owner: "+p);owner.setGameMode(net.minecraft.world.level.GameType.CREATIVE);check.accept(!owner.gameMode.destroyBlock(p)&&l.getBlockState(p).equals(s),"creative break cannot bypass protection: "+p);owner.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);}
            for(var p:List.of(glass,door)){var s=l.getBlockState(p);s.onBlockExploded(l,p,null);check.accept(l.getBlockState(p).equals(s),"explosion callback preserves original warded block: "+p);}
            admin.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R2Content.WAND.get()));check.accept(admin.getMainHandItem().getItem().onItemUseFirst(admin.getMainHandItem(),context(admin,door,Direction.NORTH))==InteractionResult.PASS&&l.getBlockState(door).is(R4Content.ARCANE_DOOR.get()),"administration does not grant dismantling rights");owner.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(R2Content.WAND.get()));var removable=POS.offset(4,0,0);check.accept(owner.getMainHandItem().getItem().onItemUseFirst(owner.getMainHandItem(),context(owner,removable.above(),Direction.NORTH)).consumesAction()&&l.isEmptyBlock(removable)&&l.isEmptyBlock(removable.above()),"owner wand removes both halves from upper hit");check.accept(l.getEntitiesOfClass(ItemEntity.class,new AABB(removable).inflate(1)).stream().filter(e->e.getItem().is(R4Content.ARCANE_DOOR_ITEM.get())).mapToInt(e->e.getItem().getCount()).sum()==1,"wand emits exactly one door");
            var temp=glass.offset(3,0,0);l.setBlockAndUpdate(temp,R4Content.WARDED_GLASS.get().defaultBlockState());tile(l,temp).assign(owner);check.accept(owner.getMainHandItem().getItem().onItemUseFirst(owner.getMainHandItem(),context(owner,temp,Direction.NORTH)).consumesAction()&&l.isEmptyBlock(temp),"owner wand recovers glass");
            thaumcraft.config.ThaumcraftConfig.WARDED_STONE.set(false);check.accept(l.getBlockState(door).getDestroySpeed(l,door)==15&&l.getBlockState(glass).getDestroySpeed(l,glass)==5&&l.getBlockState(plate).getDestroySpeed(l,plate)==2,"live toggle restores weak-mode hardness without replacing blocks");l.setBlockAndUpdate(temp,R4Content.WARDED_GLASS.get().defaultBlockState());check.accept(impostor.gameMode.destroyBlock(temp)&&l.isEmptyBlock(temp),"weak mode permits ordinary unauthorized mining");thaumcraft.config.ThaumcraftConfig.WARDED_STONE.set(true);
            check.accept(Arrays.stream(WardedGlassConnections.tiles(l,glass)).allMatch(i->i==0),"isolated glass selects first original tile on every face");l.setBlockAndUpdate(glass.east(),R4Content.WARDED_GLASS.get().defaultBlockState());check.accept(WardedGlassConnections.tiles(l,glass)[Direction.UP.get3DDataValue()]==1&&WardedGlassConnections.index(255)==11&&WardedGlassConnections.index(90)==46,"original east-neighbor, complete-window and missing-corner texture masks");
            var data=thaumcraft.data.ThaumcraftData.get(l.getServer());check.accept(data.research().get("WARDEDARCANA").recipePages().equals(List.of("ArcaneDoor","IronKey","GoldKey","ArcanePressurePlate","WardedGlass")),"five recipes reachable from original book pages");for(var id:List.of("arcane_door","warded_glass","iron_key","gold_key","arcane_pressure_plate"))check.accept(l.getRecipeManager().byKey(ResourceLocation.parse("thaumcraft:"+id)).orElseThrow().value() instanceof thaumcraft.crafting.ArcaneRecipe,"native arcane recipe loads: "+id);
            for(var key:data.research().get("WARDEDARCANA").recipePages())check.accept(l.getRecipeManager().byKey(ResourceLocation.fromNamespaceAndPath("thaumcraft",thaumcraft.data.ResearchRecipePages.resolve(key))).isPresent(),"actual book page key resolves loaded recipe: "+key);var chest=POS.offset(24,0,0);l.setBlockAndUpdate(chest,Blocks.CHEST.defaultBlockState());var inventory=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(chest);inventory.setItem(0,iron);inventory.setItem(1,gold);tile(l,plate).setting=2;l.setBlock(plate,l.getBlockState(plate).setValue(ArcanePressurePlateBlock.MODE,2),2);tile(l,plate).sync();
        }finally{thaumcraft.config.ThaumcraftConfig.WARDED_STONE.set(old);}
    }
    static void reload(ServerLevel l,BiConsumer<Boolean,String> check){for(var p:List.of(POS,POS.above(),POS.relative(Direction.SOUTH),POS.offset(20,0,0))){l.getChunkAt(p);var tile=tile(l,p);check.accept(tile!=null&&tile.ownedBy(OWNER)&&tile.ownerName().equals("OriginalOwner"),"world reload retains UUID owner and name: "+p);if(p.getX()<POS.getX()+20)check.accept(tile.permits(USER)&&!tile.administers(USER)&&tile.administers(ADMIN),"world reload retains use/admin lists: "+p);}var plate=tile(l,POS.relative(Direction.SOUTH));check.accept(plate.setting==2&&plate.getBlockState().getValue(ArcanePressurePlateBlock.MODE)==2,"plate mode and texture survive restart");l.getChunkAt(POS.offset(24,0,0));var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)l.getBlockEntity(POS.offset(24,0,0));for(int i=0;i<2;i++){var key=chest.getItem(i);check.accept(ArcaneKeyItem.bound(key)&&key.get(DataComponents.CUSTOM_DATA).copyTag().getLong("KeyPosition")==POS.asLong()&&((ArcaneKeyItem)key.getItem()).rank==i,"bound key components survive restart: "+i);}}
}
